import adaptiveTokensCss from "@pantoken/css/style.lean.css?inline";
import rebrandLightTokensCss from "@pantoken/css/style.rebrand.light.lean.css?inline";
import canvasTokensCss from "@pantoken/css/style.canvas.lean.css?inline";
import canvasHighContrastTokensCss from "@pantoken/css/style.canvas-high-contrast.lean.css?inline";
// The flat sheets above only support dark mode via the visitor's OS preference — fine for
// theme.css downloads, useless for a manual preview toggle. The attribute-scoped pair below keys
// off data-pantoken-scheme instead (see docs/conventions/scoping.md), so the live preview alone
// uses it.
import propertiesLeanCss from "@pantoken/css/properties.lean.css?inline";
import scopeLeanCss from "@pantoken/css/scope.lean.css?inline";

const LOCAL_COMPONENT_CSS = [
  baseCss,
  componentIconsCss,
  componentsCss,
  utilitiesCss,
  CUSTOM_THEME_COLORS_CSS,
  fontsCss,
].join("\n");
// Inlined once — the preview always renders from this regardless of theme.css's CDN provider, so
// its scheme forcing never depends on a network round trip either.
const PREVIEW_TOKENS_CSS = [propertiesLeanCss, scopeLeanCss].join("\n");

